import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Muestra } from '../../muestras/entities/muestra.entity';
import { Analista } from '../../analistas/entities/analista.entity';

@Injectable()
export class AsignarAnalistaRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Muestra) private readonly muestras: Repository<Muestra>,
    @InjectRepository(Analista) private readonly analistas: Repository<Analista>
  ) {}

  buscarMuestraRepository(muestraId: number) {
    return this.muestras.findOneBy({ id: muestraId });
  }

  buscarAnalistaRepository(analistaId: number) {
    return this.analistas.findOneBy({ id: analistaId });
  }

  async asignarAnalistaRepository(muestraId: number, analistaId: number, rol: string) {
    const asignacion = { muestraId, analistaId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarAnalistaRepository } from './repository';

@Injectable()
export class AsignarAnalistaService {
  constructor(private readonly repository: AsignarAnalistaRepository) {}

  async asignarAnalistaService(muestraId: number, analistaId: number, rol: string) {
    const muestra = await this.repository.buscarMuestraRepository(muestraId);
    const analista = await this.repository.buscarAnalistaRepository(analistaId);
    if (!muestra || !analista) {
      throw new NotFoundException('No existe la muestra o el analista');
    }

    try {
      return await this.repository.asignarAnalistaRepository(muestraId, analistaId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El analista ya está asignado a esa muestra');
      }
      throw error;
    }
  }
}

